package dev.trentdb.storage;import dev.trentdb.storage.format.*;import java.util.*;public final class DuckDbPrimitivePayloadReader{public static final int VECTOR_SIZE=2048;private final SingleFileBlockManager m;public DuckDbPrimitivePayloadReader(SingleFileBlockManager m){this.m=m;}public List<Long> read(DuckDbTableCreateInfo.ScalarLogicalType t,DuckDbPrimitiveColumnMetadata.Segment data,DuckDbPrimitiveColumnMetadata.Segment validity){if(t!=DuckDbTableCreateInfo.ScalarLogicalType.BOOLEAN&&t!=DuckDbTableCreateInfo.ScalarLogicalType.INTEGER&&t!=DuckDbTableCreateInfo.ScalarLogicalType.BIGINT)throw new StorageFormatException("DuckDB primitive payload type is unsupported: "+t);if(data.compressionType()!=1)throw new StorageFormatException("DuckDB primitive payload compression is unsupported: "+data.compressionType());if(data.tupleCount()>VECTOR_SIZE)throw new StorageFormatException("DuckDB primitive payload exceeds one vector: "+data.tupleCount());if(validity!=null&&(validity.compressionType()!=1||validity.tupleCount()!=data.tupleCount()))throw new StorageFormatException("DuckDB primitive validity segment is unsupported");int width=t==DuckDbTableCreateInfo.ScalarLogicalType.BIGINT?8:t==DuckDbTableCreateInfo.ScalarLogicalType.INTEGER?4:1;byte[] d=block(data.blockPointer());long bytes=Math.multiplyExact(data.tupleCount(),width);if(data.blockPointer().offset()+bytes>d.length)throw new StorageFormatException("DuckDB primitive payload crosses a block boundary");byte[] v=validity==null?null:block(validity.blockPointer());if(v!=null&&validity.blockPointer().offset()+((data.tupleCount()+7)/8)>v.length)throw new StorageFormatException("DuckDB primitive validity payload crosses a block boundary");var out=new ArrayList<Long>((int)data.tupleCount());long min=Long.MAX_VALUE,max=Long.MIN_VALUE;boolean any=false;for(int i=0;i<data.tupleCount();i++){boolean ok=v==null||((v[(int)validity.blockPointer().offset()+i/8]>>>i%8)&1)!=0;if(!ok){out.add(null);continue;}int p=(int)data.blockPointer().offset()+i*width;long x=width==8?le(d,p,8):width==4?(int)le(d,p,4):d[p]!=0?1:0;out.add(x);min=Math.min(min,x);max=Math.max(max,x);any=true;}if(any&&data.statistics().min().isPresent()&&(data.statistics().min().getAsLong()!=min||data.statistics().max().getAsLong()!=max))throw new StorageFormatException("DuckDB primitive payload disagrees with segment statistics");return Collections.unmodifiableList(out);}private byte[] block(DuckDbPrimitiveColumnMetadata.BlockPointer p){if(p.blockId()<0||p.blockId()>=m.activeHeader().blockCount())throw new StorageFormatException("DuckDB primitive payload block is outside committed range");return m.readBlock(p.blockId());}private static long le(byte[]b,int p,int n){long x=0;for(int i=0;i<n;i++)x|=(long)Byte.toUnsignedInt(b[p+i])<<8*i;return x;}}
